const todayStr = () => {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
};
const todayDow = () => new Date().getDay();
const STORE_KEY = "gym-app-v2";
const defaultData = {
  sessions: {},
  settings: { compoundRest: 180, isolationRest: 90 },
  customProgram: {},
  bodyweights: [],
};

async function loadData() {
  try {
    const r = localStorage.getItem(STORE_KEY);
    if (!r) return { ...defaultData };
    const parsed = JSON.parse(r);
    return {
      ...defaultData,
      ...parsed,
      customProgram: parsed.customProgram || {},
      bodyweights: parsed.bodyweights || [],
    };
  } catch { return { ...defaultData }; }
}
async function saveData(d) {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(d)); } catch(e) { console.error(e); }
}

function getDayExercises(dayIndex, customProgram) {
  if (customProgram && customProgram[dayIndex] && customProgram[dayIndex].length > 0) {
    return customProgram[dayIndex];
  }
  return DEFAULT_PROGRAM[dayIndex]?.exercises || [];
}

function generateId() {
  return "ex-" + Date.now() + "-" + Math.random().toString(36).substr(2, 6);
}

function getOverloadSuggestion(exercise, lastSets) {
  if (!lastSets || lastSets.length === 0) return null;
  const w = lastSets.filter(s => !s.warmup);
  if (w.length === 0) return null;
  const lw = w[w.length - 1].weight;
  const { rLo, rHi, inc, assisted } = exercise;
  const allTop = w.every(s => s.reps >= rHi);
  const anyBelow = w.some(s => s.reps < rLo);
  if (assisted) {
    if (allTop) return { weight: Math.max(0, lw - inc), action: "up", msg: `Drop assist → ${Math.max(0, lw - inc)} lbs` };
    if (anyBelow) return { weight: lw, action: "hold", msg: `Hold at ${lw} lbs` };
    return { weight: lw, action: "hold", msg: `${lw} lbs — push reps` };
  }
  if (allTop) return { weight: lw + inc, action: "up", msg: `${lw + inc} lbs` };
  if (anyBelow) return { weight: lw, action: "down", msg: `${lw} lbs — hold or drop` };
  return { weight: lw, action: "hold", msg: `${lw} lbs — push reps` };
}

function isPR(exId, weight, reps, sessions) {
  for (const [, sess] of Object.entries(sessions)) {
    const ex = sess.exercises?.[exId];
    if (!ex) continue;
    for (const s of (ex.sets || [])) {
      if (!s.warmup && s.weight >= weight && s.reps >= reps) return false;
    }
  }
  return weight > 0;
}

function findLastSession(sessions, dayIndex, beforeDate) {
  const e = Object.entries(sessions)
    .filter(([d, s]) => s.dayIndex === dayIndex && d < beforeDate)
    .sort((a, b) => b[0].localeCompare(a[0]));
  return e[0] ? { date: e[0][0], ...e[0][1] } : null;
}

function getExerciseHistory(sessions, exId, limit = 8) {
  const r = [];
  const sorted = Object.entries(sessions).sort((a, b) => b[0].localeCompare(a[0]));
  for (const [date, sess] of sorted) {
    const ex = sess.exercises?.[exId];
    if (ex?.sets?.length > 0) { r.push({ date, sets: ex.sets }); if (r.length >= limit) break; }
  }
  return r;
}

function getConsecutiveWeeks(sessions) {
  const dates = Object.keys(sessions).sort().reverse();
  if (!dates.length) return 0;
  let weeks = 1, last = gwn(new Date(dates[0]));
  for (let i = 1; i < dates.length; i++) {
    const w = gwn(new Date(dates[i]));
    if (w === last) continue;
    if (last - w === 1 || (last === 1 && w >= 51)) { weeks++; last = w; } else break;
  }
  return weeks;
}
function gwn(d) { const s = new Date(d.getFullYear(), 0, 1); return Math.ceil(((d - s) / 86400000 + s.getDay() + 1) / 7); }

function getWeekStart(date = new Date()) {
  const d = new Date(date);
  const day = d.getDay();
  d.setDate(d.getDate() - (day === 0 ? 6 : day - 1));
  d.setHours(0, 0, 0, 0);
  return d;
}

function calcPlates(target, bar = 45) {
  const avail = [45, 35, 25, 10, 5, 2.5];
  let perSide = (target - bar) / 2;
  if (perSide <= 0) return [];
  const res = [];
  for (const p of avail) { while (perSide >= p) { res.push(p); perSide -= p; } }
  return res;
}

function calc1RM(weight, reps) {
  if (reps <= 0) return weight;
  if (reps === 1) return weight;
  return Math.round(weight * (1 + reps / 30));
}

function notifyDone() {
  try { navigator.vibrate?.([200, 100, 200, 100, 300]); } catch {}
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    [830, 1050].forEach((freq, i) => {
      setTimeout(() => {
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.frequency.value = freq; o.type = "sine"; g.gain.value = 0.3;
        o.start(); o.stop(ctx.currentTime + 0.18);
      }, i * 220);
    });
  } catch {}
  if (typeof Notification !== "undefined" && Notification.permission === "granted") {
    try { new Notification("Rest complete ✓", { body: "Time for your next set!" }); } catch {}
  }
}

function requestNotifPermission() {
  if (typeof Notification !== "undefined" && Notification.permission === "default") {
    Notification.requestPermission();
  }
}

function getNextTrainingDay(fromDow, customProgram) {
  for (let i = 1; i <= 7; i++) {
    const idx = (fromDow + i) % 7;
    if (getDayExercises(idx, customProgram).length > 0) return { ...DEFAULT_PROGRAM[idx], exercises: getDayExercises(idx, customProgram) };
  }
  return null;
}

function fmt(dateStr) {
  return new Date(dateStr + "T12:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function exportData(data) {
  const json = JSON.stringify(data, null, 2);
  const blob = new Blob([json], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `gym-backup-${todayStr()}.json`;
  a.click();
  URL.revokeObjectURL(url);
}

