/* ═══════════════════════════════════════════════
   LINE CHART
   ═══════════════════════════════════════════════ */
function LineChart({ points, color = "#4f8fff", height = 90, unit = "" }) {
  if (!points || points.length < 2) {
    return (
      <div style={{ height, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <span style={{ fontSize: 12, color: "var(--text-3)" }}>Log more sessions to see chart</span>
      </div>
    );
  }
  const values = points.map(p => p.y);
  const minV = Math.min(...values);
  const maxV = Math.max(...values);
  const range = maxV - minV || 1;
  const W = 300, H = height, PX = 8, PY = 14;
  const toX = i => PX + (i / (points.length - 1)) * (W - PX * 2);
  const toY = v => H - PY - ((v - minV) / range) * (H - PY * 2);
  const pathD = points.map((p, i) => `${i === 0 ? "M" : "L"} ${toX(i)} ${toY(p.y)}`).join(" ");
  const areaD = pathD + ` L ${toX(points.length - 1)} ${H} L ${toX(0)} ${H} Z`;
  const gradId = `g${color.replace(/[^a-z0-9]/gi, "")}`;
  return (
    <div>
      <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height, display: "block" }}>
        <defs>
          <linearGradient id={gradId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="0.25" />
            <stop offset="100%" stopColor={color} stopOpacity="0.02" />
          </linearGradient>
        </defs>
        <path d={areaD} fill={`url(#${gradId})`} />
        <path d={pathD} fill="none" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
        {points.map((p, i) => (
          <circle key={i} cx={toX(i)} cy={toY(p.y)} r="3.5" fill={color} />
        ))}
      </svg>
      <div style={{ display: "flex", justifyContent: "space-between", padding: "2px 8px 0" }}>
        <span style={{ fontSize: 10, color: "var(--text-3)" }}>{points[0]?.label}</span>
        <span style={{ fontSize: 11, fontWeight: 800, color }}>
          {points[points.length - 1]?.y}{unit}
          {points.length >= 2 && (() => {
            const diff = points[points.length-1].y - points[0].y;
            if (diff === 0) return null;
            return <span style={{ fontSize: 10, marginLeft: 4, color: diff > 0 ? "var(--green)" : "var(--red)" }}>{diff > 0 ? "+" : ""}{diff}{unit}</span>;
          })()}
        </span>
        <span style={{ fontSize: 10, color: "var(--text-3)" }}>{points[points.length - 1]?.label}</span>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   REST TIMER
   ═══════════════════════════════════════════════ */
function RestTimer({ endTime, totalSeconds, onDismiss }) {
  const calcLeft = useCallback(() => Math.ceil((endTime - Date.now()) / 1000), [endTime]);
  const [left, setLeft] = useState(calcLeft);
  const fired = useRef(false);

  useEffect(() => {
    fired.current = false;
    setLeft(calcLeft());
    const id = setInterval(() => {
      const l = calcLeft();
      setLeft(l);
      if (l <= 0 && !fired.current) { fired.current = true; notifyDone(); clearInterval(id); }
    }, 500);
    return () => clearInterval(id);
  }, [endTime, calcLeft]);

  const pct = Math.max(0, left) / totalSeconds;
  const r = 36, c = 2 * Math.PI * r;
  const mins = Math.floor(Math.max(0, left) / 60);
  const secs = Math.max(0, left) % 60;
  const done = left <= 0;

  return (
    <div style={{
      flexShrink: 0, display: "flex", alignItems: "center", gap: 14, padding: "12px 16px",
      background: done ? "rgba(52,211,153,0.06)" : "rgba(79,143,255,0.05)",
      borderTop: `1px solid ${done ? "rgba(52,211,153,0.2)" : "rgba(79,143,255,0.1)"}`,
      borderBottom: "1px solid rgba(255,255,255,0.03)",
    }}>
      <div style={{ position: "relative", width: 48, height: 48, flexShrink: 0 }}>
        <svg width="48" height="48" viewBox="0 0 100 100" style={{ transform: "rotate(-90deg)" }}>
          <circle cx="50" cy="50" r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="8" />
          <circle cx="50" cy="50" r={r} fill="none"
            stroke={done ? "#34d399" : left <= 10 ? "#fbbf24" : "#4f8fff"}
            strokeWidth="8" strokeLinecap="round"
            strokeDasharray={c} strokeDashoffset={c * (1 - pct)}
            style={{ transition: "stroke-dashoffset 0.5s linear" }} />
        </svg>
        <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
          <span style={{ fontSize: done ? 11 : 10, fontWeight: 800, color: done ? "#34d399" : "var(--text-1)", fontVariantNumeric: "tabular-nums" }}>
            {done ? "GO" : `${mins}:${String(secs).padStart(2, "0")}`}
          </span>
        </div>
      </div>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: 14, fontWeight: 700, color: done ? "var(--green)" : "var(--text-1)" }}>
          {done ? "Rest complete — go!" : "Resting..."}
        </div>
        <div style={{ fontSize: 11, color: "var(--text-3)" }}>{totalSeconds}s timer</div>
      </div>
      <button onClick={onDismiss} style={{ ...s.btnG, padding: "10px 16px", fontSize: 13, fontWeight: 700 }}>
        {done ? "Done" : "Skip"}
      </button>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   FORM GUIDE
   Hardcoded cues for default exercises.
   AI-generated cues via Anthropic API for any
   custom exercise not in the FORM_CUES map.
   ═══════════════════════════════════════════════ */
function FormGuide({ exercise, dayIndex, onClose }) {
  const dayColor = DEFAULT_PROGRAM[dayIndex]?.color || "#4f8fff";
  const cues = FORM_CUES[exercise.id] || getCuesForName(exercise.name);

  return (
    <div className="slide-up" style={{
      position: "fixed", inset: 0, zIndex: 80, background: "var(--bg-0)",
      display: "flex", flexDirection: "column",
    }}>
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between",
        padding: "12px 16px", paddingTop: "max(12px, env(safe-area-inset-top))",
        borderBottom: "1px solid rgba(255,255,255,0.05)", flexShrink: 0,
      }}>
        <div>
          <div style={{ fontSize: 17, fontWeight: 800 }}>{exercise.name}</div>
          {cues?.muscles && <div style={{ fontSize: 11, color: "var(--text-3)", marginTop: 1 }}>{cues.muscles}</div>}
        </div>
        <button onClick={onClose} style={{ ...s.btnG, padding: "10px 16px", fontSize: 14, fontWeight: 700 }}>Done</button>
      </div>

      <div style={{ flex: 1, overflow: "auto", padding: "16px 20px 40px" }}>
        {cues ? (
          <>
            <div style={{ ...s.label, marginBottom: 10 }}>FORM CUES</div>
            {cues.cues.map((cue, i) => (
              <div key={i} style={{
                display: "flex", gap: 12, padding: "11px 14px", borderRadius: 12, marginBottom: 6,
                background: "var(--bg-2)", border: "1px solid rgba(255,255,255,0.04)",
              }}>
                <div style={{
                  width: 22, height: 22, borderRadius: "50%", flexShrink: 0,
                  background: `${dayColor}20`, color: dayColor,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 10, fontWeight: 800,
                }}>{i + 1}</div>
                <div style={{ fontSize: 13, fontWeight: 600, color: "var(--text-1)", lineHeight: 1.5 }}>{cue}</div>
              </div>
            ))}
          </>
        ) : (
          <div style={{ textAlign: "center", paddingTop: 40, color: "var(--text-3)", fontSize: 13 }}>
            No form cues for this exercise yet.
          </div>
        )}
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   LOGGING SCREEN
   ═══════════════════════════════════════════════ */
function LoggingScreen({ exercise, sessions, dayIndex, onSave, onClose, restDefaults, timerEndTime, timerTotalSecs, onStartTimer, onDismissTimer }) {
  const today = todayStr();
  const session = sessions[today];
  const exData = session?.exercises?.[exercise.id];
  const logged = exData?.sets || [];

  const lastSess = findLastSession(sessions, dayIndex, today);
  const lastSets = lastSess?.exercises?.[exercise.id]?.sets || [];
  const lastWorking = lastSets.filter(s => !s.warmup);
  const sug = getOverloadSuggestion(exercise, lastSets);

  const defW = logged.length > 0 ? logged[logged.length - 1].weight : (sug?.weight ?? (lastWorking[0]?.weight || 0));
  const defR = logged.length > 0 ? logged[logged.length - 1].reps : (lastWorking[0]?.reps || exercise.rLo);

  const [weight, setWeight] = useState(defW);
  const [weightStr, setWeightStr] = useState(String(defW));
  const [reps, setReps] = useState(defR);
  const [warmup, setWarmup] = useState(false);
  const [view, setView] = useState("log");
  const [editing, setEditing] = useState(null);
  const scrollRef = useRef(null);

  const [showVideo, setShowVideo] = useState(false);
  const rawQuery = encodeURIComponent(exercise.name + ' proper form cues');
  const videoUrl = exercise.videoUrl
    ? exercise.videoUrl.replace('youtube.com/results?search_query=', 'youtube.com/embed?listType=search&list=')
    : `https://www.youtube.com/embed?listType=search&list=${rawQuery}`;
  const workingDone = logged.filter(s => !s.warmup).length;
  const history = getExerciseHistory(sessions, exercise.id);
  const dayColor = DEFAULT_PROGRAM[dayIndex]?.color || "#4f8fff";
  const repLabel = exercise.perLeg ? `${exercise.rLo}/leg` : `${exercise.rLo}${exercise.rHi !== exercise.rLo ? "-" + exercise.rHi : ""}`;
  const timerActive = timerEndTime && timerEndTime > Date.now() - 3000;

  // All-time PR: best weight × best reps ever logged for this exercise
  const allTimePR = (() => {
    let best = null;
    for (const [, sess] of Object.entries(sessions)) {
      const sets = sess.exercises?.[exercise.id]?.sets || [];
      for (const st of sets) {
        if (!st.warmup && st.weight > 0) {
          if (!best || st.weight > best.weight || (st.weight === best.weight && st.reps > best.reps)) {
            best = { weight: st.weight, reps: st.reps };
          }
        }
      }
    }
    return best;
  })();

  // Session volume: sum of weight × reps for all working sets this session
  const sessionVolume = logged
    .filter(s => !s.warmup)
    .reduce((sum, s) => sum + s.weight * s.reps, 0);

  const chartPoints = history.slice().reverse().map(h => {
    const ws = h.sets.filter(s => !s.warmup);
    if (!ws.length) return null;
    return { y: ws[ws.length - 1].weight, label: fmt(h.date) };
  }).filter(Boolean);

  function logSet() {
    const pr = !warmup && isPR(exercise.id, weight, reps, sessions);
    const ns = { weight, reps, warmup, pr, ts: Date.now() };
    const updated = editing !== null ? logged.map((st, i) => i === editing ? ns : st) : [...logged, ns];
    onSave(exercise.id, updated, exData?.swappedTo || null, exercise.name);
    setEditing(null);
    if (!warmup && editing === null) onStartTimer(exercise.compound ? restDefaults.compound : restDefaults.isolation);
    setTimeout(() => scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" }), 50);
  }

  function deleteSet(idx) { onSave(exercise.id, logged.filter((_, i) => i !== idx), exData?.swappedTo || null, exercise.name); }

  function dupLast() {
    if (!logged.length) return;
    const l = logged[logged.length - 1];
    const pr = !l.warmup && isPR(exercise.id, l.weight, l.reps, sessions);
    onSave(exercise.id, [...logged, { ...l, pr, ts: Date.now() }], exData?.swappedTo || null, exercise.name);
    if (!l.warmup) onStartTimer(exercise.compound ? restDefaults.compound : restDefaults.isolation);
  }

  function startEdit(idx) {
    const x = logged[idx];
    setWeight(x.weight); setWeightStr(String(x.weight)); setReps(x.reps); setWarmup(x.warmup); setEditing(idx);
  }

  return (
    <div className="slide-up" style={{ position: "fixed", inset: 0, zIndex: 60, background: "var(--bg-0)", display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 16px", paddingTop: "max(12px, env(safe-area-inset-top))", flexShrink: 0 }}>
        <button onClick={onClose} style={{ ...s.btnG, padding: "10px 16px", fontSize: 14, display: "flex", alignItems: "center", gap: 6 }}>
          <span style={{ fontSize: 18, lineHeight: 1 }}>‹</span> Back
        </button>
        <div style={{ display: "flex", gap: 4 }}>
          {["log", "history"].map(v => (
            <button key={v} onClick={() => setView(v)} style={{
              padding: "8px 14px", borderRadius: 10, fontSize: 13, fontWeight: 600, border: "none", cursor: "pointer", fontFamily: "inherit",
              background: view === v ? "rgba(79,143,255,0.12)" : "transparent",
              color: view === v ? "#4f8fff" : "var(--text-3)",
            }}>{v === "log" ? "Log" : "History"}</button>
          ))}
        </div>
      </div>

      <div style={{ padding: "0 20px 10px", flexShrink: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
          <h2 style={{ fontSize: 21, fontWeight: 800, flex: 1, lineHeight: 1.2 }}>{exData?.swappedTo || exercise.name}</h2>
          {(exercise.videoUrl || exercise.name) && (
            <button onClick={() => setShowVideo(true)} style={{
              fontSize: 11, padding: "5px 10px", borderRadius: 8, border: "1px solid rgba(79,143,255,0.25)",
              background: "rgba(79,143,255,0.1)", color: "var(--accent)", cursor: "pointer", fontFamily: "inherit", fontWeight: 700,
              WebkitUserSelect: "none", userSelect: "none",
            }}>▶ Form</button>
          )}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
          <span style={{ fontSize: 12, fontWeight: 700, padding: "4px 10px", borderRadius: 8, background: `${dayColor}18`, color: dayColor }}>
            {exercise.sets} x {repLabel}
          </span>
          <div style={{ display: "flex", gap: 3 }}>
            {Array.from({ length: exercise.sets }).map((_, i) => (
              <div key={i} style={{ width: 8, height: 8, borderRadius: 4, background: i < workingDone ? "#34d399" : "rgba(255,255,255,0.08)", transition: "all 0.2s" }} />
            ))}
          </div>
          {exercise.assisted && <span style={{ fontSize: 10, padding: "3px 7px", borderRadius: 6, background: "rgba(167,139,250,0.12)", color: "#a78bfa", fontWeight: 700 }}>Assisted</span>}
        </div>

        {/* PR + Volume row */}
        <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
          {allTimePR && (
            <div style={{
              flex: 1, padding: "8px 12px", borderRadius: 10,
              background: "rgba(251,191,36,0.06)", border: "1px solid rgba(251,191,36,0.15)",
              display: "flex", flexDirection: "column", gap: 1,
            }}>
              <div style={{ fontSize: 9, fontWeight: 800, color: "var(--amber)", letterSpacing: 0.8 }}>ALL-TIME PR</div>
              <div style={{ fontSize: 15, fontWeight: 800, color: "var(--text-1)" }}>
                {allTimePR.weight} <span style={{ fontSize: 11, color: "var(--text-3)", fontWeight: 600 }}>lbs</span>
                <span style={{ fontSize: 13, color: "var(--text-3)", fontWeight: 600, marginLeft: 4 }}>× {allTimePR.reps}</span>
              </div>
            </div>
          )}
          {sessionVolume > 0 && (
            <div style={{
              flex: 1, padding: "8px 12px", borderRadius: 10,
              background: "rgba(79,143,255,0.06)", border: "1px solid rgba(79,143,255,0.15)",
              display: "flex", flexDirection: "column", gap: 1,
            }}>
              <div style={{ fontSize: 9, fontWeight: 800, color: "var(--accent)", letterSpacing: 0.8 }}>SESSION VOLUME</div>
              <div style={{ fontSize: 15, fontWeight: 800, color: "var(--text-1)" }}>
                {sessionVolume.toLocaleString()} <span style={{ fontSize: 11, color: "var(--text-3)", fontWeight: 600 }}>lbs</span>
              </div>
            </div>
          )}
        </div>
        {sug && (
          <div style={{
            marginTop: 8, padding: "8px 12px", borderRadius: 10, fontSize: 12, fontWeight: 600,
            background: sug.action === "up" ? "var(--green-dim)" : sug.action === "down" ? "var(--red-dim)" : "var(--bg-2)",
            color: sug.action === "up" ? "var(--green)" : sug.action === "down" ? "var(--red)" : "var(--text-2)",
            display: "flex", alignItems: "center", gap: 6,
          }}>
            <span style={{ fontWeight: 800, fontSize: 14 }}>{sug.action === "up" ? "↑" : sug.action === "down" ? "↓" : "→"}</span>
            {sug.action === "up" ? `Target: ${sug.msg}` : sug.msg}
          </div>
        )}
      </div>

      {view === "history" ? (
        <div style={{ flex: 1, overflow: "auto", padding: "0 20px 24px" }}>
          {chartPoints.length >= 2 && (
            <div style={{ ...s.card, padding: "14px 14px 10px", marginBottom: 12 }}>
              <div style={{ ...s.label, marginBottom: 8 }}>WEIGHT TREND</div>
              <LineChart points={chartPoints} color={dayColor} unit=" lbs" />
            </div>
          )}
          {history.length === 0 && <p style={{ color: "var(--text-3)", textAlign: "center", marginTop: 40 }}>No history yet</p>}
          {history.map((h, i) => (
            <div key={i} className="fade-in" style={{ ...s.card, padding: 14, marginBottom: 8 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-3)", marginBottom: 6 }}>{fmt(h.date)}</div>
              {h.sets.map((st, j) => (
                <div key={j} style={{ display: "flex", gap: 8, fontSize: 14, padding: "2px 0", color: st.warmup ? "var(--text-3)" : "var(--text-1)" }}>
                  <span style={{ width: 18, fontWeight: 700, color: "var(--text-3)" }}>{st.warmup ? "W" : j + 1}</span>
                  <span style={{ fontWeight: 700 }}>{st.weight}</span><span style={{ color: "var(--text-3)" }}>x</span><span style={{ fontWeight: 700 }}>{st.reps}</span>
                  {st.pr && <span style={{ color: "var(--amber)", fontSize: 10, fontWeight: 800 }}>PR</span>}
                </div>
              ))}
            </div>
          ))}
        </div>
      ) : (
        <>
          <div ref={scrollRef} style={{ flex: 1, overflow: "auto", padding: "0 16px 12px" }}>
            {lastWorking.length > 0 && (
              <div style={{ padding: "8px 12px", borderRadius: 10, background: "rgba(255,255,255,0.02)", border: "1px solid rgba(255,255,255,0.03)", marginBottom: 8 }}>
                <div style={{ ...s.label, marginBottom: 4, fontSize: 10 }}>PREV {lastSess ? fmt(lastSess.date) : ""}</div>
                <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                  {lastSets.map((ls, i) => (
                    <span key={i} style={{ fontSize: 12, color: ls.warmup ? "var(--text-3)" : "var(--text-2)", fontWeight: 600 }}>
                      {ls.warmup ? "W:" : ""}{ls.weight}x{ls.reps}
                    </span>
                  ))}
                </div>
              </div>
            )}
            {logged.map((st, i) => {
              const wIdx = logged.slice(0, i + 1).filter(x => !x.warmup).length;
              return (
                <div key={i} className="fade-in" style={{
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                  padding: "12px 14px", borderRadius: 14, marginBottom: 5,
                  background: st.warmup ? "rgba(167,139,250,0.04)" : "var(--bg-2)",
                  border: st.pr ? "1px solid rgba(251,191,36,0.25)" : "1px solid rgba(255,255,255,0.03)",
                }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <span style={{ width: 22, fontSize: 11, fontWeight: 800, color: st.warmup ? "var(--purple)" : "var(--text-3)", textAlign: "center" }}>
                      {st.warmup ? "W" : wIdx}
                    </span>
                    <span style={{ fontSize: 17, fontWeight: 700 }}>{st.weight}</span>
                    <span style={{ color: "var(--text-3)" }}>x</span>
                    <span style={{ fontSize: 17, fontWeight: 700 }}>{st.reps}</span>
                    {st.pr && <span style={{ fontSize: 9, fontWeight: 800, padding: "2px 6px", borderRadius: 5, background: "var(--amber-dim)", color: "var(--amber)" }}>PR!</span>}
                  </div>
                  <div style={{ display: "flex", gap: 4 }}>
                    <button onClick={() => startEdit(i)} style={{ width: 34, height: 34, borderRadius: 9, border: "none", background: "rgba(255,255,255,0.04)", color: "var(--text-3)", fontSize: 14, cursor: "pointer" }}>✎</button>
                    <button onClick={() => deleteSet(i)} style={{ width: 34, height: 34, borderRadius: 9, border: "none", background: "rgba(248,113,113,0.06)", color: "var(--red)", fontSize: 13, cursor: "pointer" }}>✕</button>
                  </div>
                </div>
              );
            })}
            {logged.length > 0 && (
              <button onClick={dupLast} style={{
                width: "100%", padding: 12, borderRadius: 12, fontSize: 13, fontWeight: 600, fontFamily: "inherit",
                background: "none", border: "1px dashed rgba(255,255,255,0.07)", color: "var(--text-3)", cursor: "pointer",
              }}>Duplicate Last Set</button>
            )}
          </div>

          {timerActive && <RestTimer endTime={timerEndTime} totalSeconds={timerTotalSecs} onDismiss={onDismissTimer} />}

          <div style={{
            flexShrink: 0, background: "var(--bg-0)",
            padding: "14px 16px", paddingBottom: "max(14px, env(safe-area-inset-bottom))",
            borderTop: "1px solid rgba(255,255,255,0.04)",
          }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 5, marginBottom: 10 }}>
              {[10, 5, 2.5].map(v => (
                <button key={v} onClick={() => { const nw = Math.max(0, +(weight - v).toFixed(1)); setWeight(nw); setWeightStr(String(nw)); }}
                  style={{ ...s.btnG, width: 48, height: 42, fontSize: 12, fontWeight: 700, color: "var(--red)", padding: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  -{v}
                </button>
              ))}
              <div style={{ textAlign: "center", width: 76 }}>
                <input type="number" inputMode="decimal" value={weightStr}
                  onChange={e => { setWeightStr(e.target.value); setWeight(parseFloat(e.target.value) || 0); }}
                  onFocus={e => e.target.select()}
                  onBlur={() => setWeightStr(String(weight))}
                  style={{ width: "100%", textAlign: "center", fontSize: 26, fontWeight: 800, background: "transparent", border: "none", borderBottom: "2px solid rgba(79,143,255,0.3)", color: "var(--text-1)", fontFamily: "inherit", fontVariantNumeric: "tabular-nums", padding: "2px 0", outline: "none" }} />
                <div style={{ fontSize: 9, fontWeight: 600, color: "var(--text-3)", textTransform: "uppercase", marginTop: 2 }}>
                  {exercise.assisted ? "assist" : "lbs"}
                </div>
              </div>
              {[2.5, 5, 10].map(v => (
                <button key={v} onClick={() => { const nw = +(weight + v).toFixed(1); setWeight(nw); setWeightStr(String(nw)); }}
                  style={{ ...s.btnG, width: 48, height: 42, fontSize: 12, fontWeight: 700, color: "var(--green)", padding: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  +{v}
                </button>
              ))}
            </div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginBottom: 10 }}>
              <button onClick={() => setReps(r => Math.max(1, r - 1))}
                style={{ ...s.btnG, width: 54, height: 54, fontSize: 20, fontWeight: 800, color: "var(--red)", padding: 0, borderRadius: 14, display: "flex", alignItems: "center", justifyContent: "center" }}>-</button>
              <div style={{ textAlign: "center", width: 76 }}>
                <div style={{ fontSize: 34, fontWeight: 800, fontVariantNumeric: "tabular-nums" }}>{reps}</div>
                <div style={{ fontSize: 9, fontWeight: 600, color: "var(--text-3)" }}>REPS ({exercise.rLo}-{exercise.rHi})</div>
              </div>
              <button onClick={() => setReps(r => r + 1)}
                style={{ ...s.btnG, width: 54, height: 54, fontSize: 20, fontWeight: 800, color: "var(--green)", padding: 0, borderRadius: 14, display: "flex", alignItems: "center", justifyContent: "center" }}>+</button>
              <button onClick={() => setWarmup(!warmup)} style={{
                width: 54, height: 54, borderRadius: 14, border: "none", fontSize: 10, fontWeight: 800, cursor: "pointer", fontFamily: "inherit",
                background: warmup ? "rgba(167,139,250,0.18)" : "var(--bg-2)",
                color: warmup ? "#a78bfa" : "var(--text-3)", letterSpacing: 0.3,
              }}>{warmup ? "WARM" : "WORK"}</button>
            </div>
            <button onClick={logSet} style={{
              ...s.btnP, width: "100%", height: 52, fontSize: 16, fontFamily: "inherit",
              background: editing !== null ? "linear-gradient(135deg, #d97706, #b45309)" : s.btnP.background,
            }}>{editing !== null ? "Update Set" : `Log ${warmup ? "Warmup" : "Set"}`}</button>
            {editing !== null && (
              <button onClick={() => { setEditing(null); setWeight(defW); setWeightStr(String(defW)); setReps(defR); setWarmup(false); }}
                style={{ width: "100%", padding: 10, border: "none", background: "none", color: "var(--text-3)", fontSize: 13, cursor: "pointer", fontFamily: "inherit", marginTop: 2 }}>Cancel</button>
            )}
          </div>
        </>
      )}

      {showVideo && (
        <FormGuide exercise={exercise} dayIndex={dayIndex} onClose={() => setShowVideo(false)} />
      )}
    </div>
  );
}

