function WorkoutView({ data, activeDow, onStartExercise, onSkip, onSaveNotes, onSaveCardio, onRemoveCardio }) {
  const today = todayStr();
  const dayPlan = DEFAULT_PROGRAM[activeDow];
  const exercises = getDayExercises(activeDow, data.customProgram);
  const isRest = exercises.length === 0;
  const session = data.sessions[today];
  const lastSess = findLastSession(data.sessions, activeDow, today);
  const weeks = getConsecutiveWeeks(data.sessions);
  const [notes, setNotes] = useState(session?.notes || "");
  const [cardio, setCardio] = useState({ type: "Treadmill", duration: 30, incline: 12, speed: 3.5, notes: "" });
  const [showCardioForm, setShowCardioForm] = useState(false);
  const [cardioSaved, setCardioSaved] = useState(false);
  const cardioEntries = Array.isArray(session?.cardio) ? session.cardio : session?.cardio ? [session.cardio] : [];
  const isToday = activeDow === todayDow();

  if (isRest) {
    const next = getNextTrainingDay(activeDow, data.customProgram);
    return (
      <div className="fade-in" style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minHeight: "60vh", padding: 24 }}>
        <div style={{ width: 80, height: 80, borderRadius: "50%", background: "rgba(79,143,255,0.06)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 40, marginBottom: 20 }}>😴</div>
        <h2 style={{ fontSize: 24, fontWeight: 800, marginBottom: 4 }}>Rest Day</h2>
        <p style={{ color: "var(--text-3)", fontSize: 14, marginBottom: 24 }}>{dayPlan.day}</p>
        {next && (
          <div style={{ ...s.card, ...s.cardGlow, padding: 20, textAlign: "center", width: "100%" }}>
            <div style={{ ...s.label, marginBottom: 4 }}>NEXT SESSION</div>
            <div style={{ fontSize: 20, fontWeight: 800, color: next.color || "var(--accent)" }}>{next.day} — {next.name}</div>
            <div style={{ fontSize: 13, color: "var(--text-3)", marginTop: 4 }}>{next.exercises.length} exercises</div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="fade-in" style={{ paddingBottom: 100 }}>
      <div style={{ padding: "0 20px 12px" }}>
        <div style={{ fontSize: 12, fontWeight: 600, color: "var(--text-3)" }}>
          {isToday ? new Date().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" }) : dayPlan.day + " Preview"}
        </div>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: dayPlan.color || "var(--text-1)" }}>{dayPlan.name}</h1>
        {!isToday && <div style={{ fontSize: 12, color: "var(--amber)", fontWeight: 600, marginTop: 2 }}>Viewing only. Log on the actual day.</div>}
      </div>

      {weeks >= 4 && isToday && (
        <div style={{ margin: "0 20px 10px", padding: "10px 14px", borderRadius: 12, background: "var(--amber-dim)", border: "1px solid rgba(251,191,36,0.12)" }}>
          <span style={{ fontSize: 13, fontWeight: 600, color: "var(--amber)" }}>Week {weeks}. Consider a deload if fatigue is building.</span>
        </div>
      )}

      <div style={{ padding: "0 16px" }}>
          {exercises.map(ex => {
          const exD = session?.exercises?.[ex.id];
          const sets = exD?.sets || [];
          const ws = sets.filter(s => !s.warmup);
          const skipped = exD?.skipped;
          const done = ws.length >= ex.sets;
          const lastEx = lastSess?.exercises?.[ex.id];
          const lastW = lastEx?.sets?.filter(s => !s.warmup) || [];
          const sug = getOverloadSuggestion(ex, lastEx?.sets || []);
          const hasPR = sets.some(s => s.pr);
          const repLabel = ex.perLeg ? `${ex.rLo}/leg` : `${ex.rLo}${ex.rHi !== ex.rLo ? "-" + ex.rHi : ""}`;
          const videoUrl = ex.videoUrl || exD?.videoUrl;

          // Skipped: render as div so Undo button works on iOS
          if (skipped && isToday) {
            return (
              <div key={ex.id} style={{
                display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "14px 16px", borderRadius: 14, marginBottom: 6,
                background: "rgba(255,255,255,0.02)", border: "1px solid rgba(255,255,255,0.04)",
              }}>
                <div>
                  <div style={{ fontSize: 15, fontWeight: 700, color: "var(--text-3)" }}>{ex.name}</div>
                  <div style={{ fontSize: 11, color: "var(--text-3)", opacity: 0.6 }}>{ex.sets}x{repLabel} · Skipped</div>
                </div>
                <button onClick={() => onSkip(ex.id, true)} style={{
                  fontSize: 11, padding: "6px 12px", borderRadius: 7, fontWeight: 700, fontFamily: "inherit",
                  background: "rgba(248,113,113,0.08)", color: "var(--red)",
                  border: "1px solid rgba(248,113,113,0.2)", cursor: "pointer", flexShrink: 0,
                }}>Undo</button>
              </div>
            );
          }

          return (
            <button key={ex.id} onClick={() => isToday && onStartExercise(ex)} disabled={!isToday}
              style={{
                width: "100%", textAlign: "left", padding: "14px 16px", borderRadius: 14, marginBottom: 6,
                cursor: isToday ? "pointer" : "default", fontFamily: "inherit", border: "none",
                background: done ? "linear-gradient(145deg, rgba(52,211,153,0.06), rgba(52,211,153,0.02))" : "linear-gradient(145deg, #111b2e, #0d1526)",
                outline: hasPR ? "1px solid rgba(251,191,36,0.2)" : done ? "1px solid rgba(52,211,153,0.1)" : "1px solid rgba(255,255,255,0.03)",
              }}>
              <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between" }}>
                <div style={{ flex: 1 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 3, flexWrap: "wrap" }}>
                    <span style={{ fontSize: 15, fontWeight: 700, color: done ? "var(--green)" : "var(--text-1)" }}>{exD?.swappedTo || ex.name}</span>
                    {done && <span style={{ color: "var(--green)", fontSize: 13 }}>✓</span>}
                    {hasPR && <span style={{ fontSize: 9, fontWeight: 800, padding: "2px 5px", borderRadius: 4, background: "var(--amber-dim)", color: "var(--amber)" }}>PR</span>}
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                    <span style={{ fontSize: 11, fontWeight: 700, color: dayPlan.color, opacity: 0.7 }}>{ex.sets}x{repLabel}</span>
                    {lastW.length > 0 && <span style={{ fontSize: 11, color: "var(--text-3)" }}>Prev: {lastW.map(s => `${s.weight}x${s.reps}`).join("  ")}</span>}
                  </div>
                  {sug && !done && isToday && (
                    <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 4 }}>
                      <span style={{
                        fontSize: 10, padding: "2px 7px", borderRadius: 5, fontWeight: 800,
                        background: sug.action === "up" ? "var(--green-dim)" : sug.action === "down" ? "var(--red-dim)" : "var(--bg-3)",
                        color: sug.action === "up" ? "var(--green)" : sug.action === "down" ? "var(--red)" : "var(--text-2)",
                      }}>
                        {sug.action === "up" ? "↑ GO UP" : sug.action === "down" ? "↓ HOLD" : "→ SAME"}
                      </span>
                      <span style={{ fontSize: 12, fontWeight: 700, color: sug.action === "up" ? "var(--green)" : sug.action === "down" ? "var(--red)" : "var(--text-2)" }}>
                        {sug.msg}
                      </span>
                    </div>
                  )}
                  {ws.length > 0 && !done && <div style={{ fontSize: 11, color: "var(--text-2)", marginTop: 3 }}>Today: {ws.map(s => `${s.weight}x${s.reps}`).join("  ")}</div>}
                </div>
                {isToday && !done && (
                  <button onClick={e => { e.stopPropagation(); onSkip(ex.id, false); }} style={{
                    fontSize: 11, padding: "6px 12px", borderRadius: 7, fontWeight: 700, fontFamily: "inherit",
                    background: "rgba(255,255,255,0.05)", color: "var(--text-2)",
                    border: "1px solid rgba(255,255,255,0.08)", cursor: "pointer", flexShrink: 0, marginLeft: 8,
                  }}>Skip</button>
                )}
              </div>
              {(
                <div style={{ display: "flex", gap: 3, marginTop: 8 }}>
                  {Array.from({ length: ex.sets }).map((_, i) => (
                    <div key={i} style={{ flex: 1, height: 3, borderRadius: 2, background: i < ws.length ? (done ? "var(--green)" : dayPlan.color) : "rgba(255,255,255,0.05)", transition: "all 0.3s" }} />
                  ))}
                </div>
              )}
            </button>
          );
        })}
      </div>

      {isToday && (
        <div style={{ padding: "8px 20px 0" }}>
          <textarea value={notes} onChange={e => { setNotes(e.target.value); onSaveNotes(e.target.value); }}
            placeholder="Session notes..." rows={2}
            style={{ ...s.inp, fontSize: 14, resize: "none", padding: "10px 14px" }} />
        </div>
      )}

      {/* CARDIO SECTION */}
      {isToday && (
        <div style={{ padding: "10px 20px 0" }}>
          {/* Logged entries */}
          {cardioEntries.map((entry, i) => (
            <div key={i} style={{
              display: "flex", alignItems: "center", justifyContent: "space-between",
              padding: "10px 14px", borderRadius: 12, marginBottom: 6,
              background: "rgba(52,211,153,0.06)", border: "1px solid rgba(52,211,153,0.12)",
            }}>
              <div>
                <div style={{ fontSize: 13, fontWeight: 700, color: "var(--green)" }}>
                  {entry.type} · {entry.duration} min
                </div>
                {entry.type === "Treadmill" && (
                  <div style={{ fontSize: 11, color: "var(--text-3)", marginTop: 2 }}>
                    {entry.incline}% incline · {entry.speed} mph
                  </div>
                )}
              </div>
              <button onClick={() => onRemoveCardio(i)} style={{
                width: 28, height: 28, borderRadius: 7, border: "none",
                background: "rgba(248,113,113,0.08)", color: "var(--red)", fontSize: 13, cursor: "pointer",
              }}>✕</button>
            </div>
          ))}

          {/* Add form or button */}
          {!showCardioForm ? (
            <button onClick={() => setShowCardioForm(true)} style={{
              width: "100%", padding: "13px 0", borderRadius: 14, fontSize: 14, fontWeight: 700, border: "none", cursor: "pointer", fontFamily: "inherit",
              background: "rgba(52,211,153,0.06)", color: "var(--green)",
              border: "1px dashed rgba(52,211,153,0.2)",
            }}>
              {cardioEntries.length > 0 ? "+ Add More Cardio" : "+ Log Cardio"}
            </button>
          ) : (
            <div style={{ ...s.card, padding: 16, border: "1px solid rgba(52,211,153,0.1)" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                <div style={{ ...s.label, marginBottom: 0 }}>CARDIO</div>
                <button onClick={() => setShowCardioForm(false)} style={{ fontSize: 11, color: "var(--text-3)", background: "none", border: "none", cursor: "pointer", fontFamily: "inherit" }}>Cancel</button>
              </div>
              <div style={{ display: "flex", gap: 6, marginBottom: 12, flexWrap: "wrap" }}>
                {["Treadmill", "Bike", "Run", "Walk", "Other"].map(t => (
                  <button key={t} onClick={() => setCardio(c => ({ ...c, type: t }))} style={{
                    padding: "7px 12px", borderRadius: 8, fontSize: 12, fontWeight: 700, border: "none", cursor: "pointer", fontFamily: "inherit",
                    background: cardio.type === t ? "rgba(52,211,153,0.15)" : "var(--bg-2)",
                    color: cardio.type === t ? "var(--green)" : "var(--text-3)",
                  }}>{t}</button>
                ))}
              </div>
              <div style={{ display: "flex", gap: 8, marginBottom: cardio.type === "Treadmill" ? 10 : 0 }}>
                <div style={{ flex: 1 }}>
                  <div style={s.label}>DURATION (min)</div>
                  <input type="number" inputMode="numeric" value={cardio.duration}
                    onChange={e => setCardio(c => ({ ...c, duration: e.target.value }))}
                    style={{ ...s.inp, textAlign: "center", fontSize: 18, padding: "8px 0" }} />
                </div>
                {cardio.type === "Treadmill" && (
                  <>
                    <div style={{ flex: 1 }}>
                      <div style={s.label}>INCLINE (%)</div>
                      <input type="number" inputMode="decimal" value={cardio.incline}
                        onChange={e => setCardio(c => ({ ...c, incline: e.target.value }))}
                        style={{ ...s.inp, textAlign: "center", fontSize: 18, padding: "8px 0" }} />
                    </div>
                    <div style={{ flex: 1 }}>
                      <div style={s.label}>SPEED (mph)</div>
                      <input type="number" inputMode="decimal" value={cardio.speed}
                        onChange={e => setCardio(c => ({ ...c, speed: e.target.value }))}
                        style={{ ...s.inp, textAlign: "center", fontSize: 18, padding: "8px 0" }} />
                    </div>
                  </>
                )}
              </div>
              <button onClick={() => {
                onSaveCardio(cardio);
                setShowCardioForm(false);
                setCardioSaved(true);
                setCardio({ type: "Treadmill", duration: 30, incline: 12, speed: 3.5, notes: "" });
                setTimeout(() => setCardioSaved(false), 2000);
              }} style={{
                ...s.btnP, width: "100%", height: 44, fontSize: 14, fontFamily: "inherit", marginTop: 10,
                background: cardioSaved ? "linear-gradient(135deg, #34d399, #059669)" : s.btnP.background,
              }}>
                {cardioSaved ? "✓ Saved" : "Save Cardio"}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════
   HISTORY VIEW
   ═══════════════════════════════════════════════ */
function HistoryView({ data }) {
  const { sessions, customProgram } = data;
  const [sel, setSel] = useState(null);

  // Collect all current program exercise IDs
  const currentIds = new Set();
  [1, 2, 4, 5, 6].forEach(idx => {
    getDayExercises(idx, customProgram).forEach(ex => currentIds.add(ex.id));
  });

  // Find archived exercise IDs (in sessions but not in current program)
  const archivedMap = {};
  Object.values(sessions).forEach(sess => {
    Object.keys(sess.exercises || {}).forEach(exId => {
      if (!currentIds.has(exId) && sess.exercises[exId]?.sets?.length > 0) {
        if (!archivedMap[exId]) {
          archivedMap[exId] = {
            id: exId,
            name: sess.exercises[exId].name || exId,
          };
        }
      }
    });
  });

  if (sel) {
    const hist = getExerciseHistory(sessions, sel.id, 10);
    const chartPoints = hist.slice().reverse().map(h => {
      const ws = h.sets.filter(s => !s.warmup);
      if (!ws.length) return null;
      return { y: ws[ws.length - 1].weight, label: fmt(h.date) };
    }).filter(Boolean);

    return (
      <div className="fade-in" style={{ padding: 20, paddingBottom: 100 }}>
        <button onClick={() => setSel(null)} style={{ ...s.btnG, padding: "10px 16px", fontSize: 13, marginBottom: 16 }}>‹ Back</button>
        <h2 style={{ fontSize: 20, fontWeight: 800, marginBottom: 14 }}>{sel.name}</h2>
        {chartPoints.length >= 2 && (
          <div style={{ ...s.card, padding: "14px 14px 10px", marginBottom: 14 }}>
            <div style={{ ...s.label, marginBottom: 8 }}>WEIGHT TREND</div>
            <LineChart points={chartPoints} color="#4f8fff" unit=" lbs" />
          </div>
        )}
        {hist.length === 0 && <p style={{ color: "var(--text-3)" }}>No data yet</p>}
        {hist.map((h, i) => (
          <div key={i} className="fade-in" style={{ ...s.card, padding: 14, marginBottom: 8 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-3)", marginBottom: 6 }}>{fmt(h.date)}</div>
            {h.sets.map((st, j) => (
              <div key={j} style={{ display: "flex", gap: 8, fontSize: 14, padding: "2px 0", color: st.warmup ? "var(--text-3)" : "var(--text-1)" }}>
                <span style={{ width: 18, fontWeight: 700, color: "var(--text-3)" }}>{st.warmup ? "W" : j + 1}</span>
                <span style={{ fontWeight: 700 }}>{st.weight}</span><span style={{ color: "var(--text-3)" }}>x</span><span style={{ fontWeight: 700 }}>{st.reps}</span>
                {st.pr && <span style={{ color: "var(--amber)", fontSize: 10, fontWeight: 800 }}>PR</span>}
              </div>
            ))}
          </div>
        ))}
      </div>
    );
  }

  return (
    <div className="fade-in" style={{ padding: 20, paddingBottom: 100 }}>
      <h2 style={{ fontSize: 20, fontWeight: 800, marginBottom: 14 }}>History</h2>
      {[1, 2, 4, 5, 6].map(dayIdx => {
        const d = DEFAULT_PROGRAM[dayIdx];
        const exList = getDayExercises(dayIdx, customProgram);
        return (
          <div key={dayIdx} style={{ marginBottom: 14 }}>
            <div style={{ fontSize: 10, fontWeight: 800, color: d.color, textTransform: "uppercase", letterSpacing: 1, marginBottom: 5, paddingLeft: 2 }}>{d.day} — {d.name}</div>
            {exList.map(ex => {
              const h = getExerciseHistory(sessions, ex.id, 1);
              const last = h[0]?.sets?.filter(s => !s.warmup) || [];
              return (
                <button key={ex.id} onClick={() => setSel(ex)} style={{
                  width: "100%", textAlign: "left", display: "flex", justifyContent: "space-between", alignItems: "center",
                  padding: "12px 14px", borderRadius: 12, marginBottom: 3, cursor: "pointer", fontFamily: "inherit",
                  background: "var(--bg-2)", border: "1px solid rgba(255,255,255,0.03)",
                }}>
                  <span style={{ fontSize: 14, fontWeight: 600, color: "var(--text-1)" }}>{ex.name}</span>
                  <span style={{ fontSize: 14, fontWeight: 800, color: "var(--text-1)", fontVariantNumeric: "tabular-nums" }}>
                    {last.length > 0 ? `${last[0].weight} x ${last[0].reps}` : "---"}
                  </span>
                </button>
              );
            })}
          </div>
        );
      })}
      {Object.keys(archivedMap).length > 0 && (
        <div style={{ marginTop: 10 }}>
          <div style={{ fontSize: 10, fontWeight: 800, color: "var(--text-3)", textTransform: "uppercase", letterSpacing: 1, marginBottom: 8 }}>Archived</div>
          {Object.values(archivedMap).map(({ id: exId, name: exName }) => {
            const h = getExerciseHistory(sessions, exId, 1);
            const last = h[0]?.sets?.filter(s => !s.warmup) || [];
            return (
              <button key={exId} onClick={() => setSel({ id: exId, name: exName })} style={{
                width: "100%", textAlign: "left", display: "flex", justifyContent: "space-between", alignItems: "center",
                padding: "12px 14px", borderRadius: 12, marginBottom: 3, cursor: "pointer", fontFamily: "inherit",
                background: "rgba(255,255,255,0.02)", border: "1px solid rgba(255,255,255,0.03)", opacity: 0.6,
              }}>
                <span style={{ fontSize: 13, fontWeight: 600, color: "var(--text-2)" }}>{exName}</span>
                <span style={{ fontSize: 13, fontWeight: 700, color: "var(--text-2)" }}>
                  {last.length > 0 ? `${last[0].weight} x ${last[0].reps}` : "---"}
                </span>
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

/* ═══════════════════════════════════════════════
   STATS VIEW
   ═══════════════════════════════════════════════ */
function StatsView({ data, onSaveBodyweight }) {
  const { sessions, bodyweights = [] } = data;
  const [bwStr, setBwStr] = useState("");
  const [bwSaved, setBwSaved] = useState(false);
  const [expandedSession, setExpandedSession] = useState(null);

  const today = todayStr();
  const todayBw = bodyweights.find(b => b.date === today);

  const weeks = getConsecutiveWeeks(sessions);

  // This week's training days
  const weekStart = getWeekStart();
  const weekDates = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + i);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
  });

  const trainingDayIndices = [1, 2, 4, 5, 6];
  const weekSessions = weekDates.map((date, i) => {
    const dow = (weekStart.getDay() + i) % 7 || 7; // 1=Mon ... 7=Sun
    const actualDow = (weekStart.getDay() + i) % 7;
    const sess = sessions[date];
    const isTraining = trainingDayIndices.includes(actualDow);
    const exList = getDayExercises(actualDow, data.customProgram);
    const done = sess && exList.length > 0 && exList.filter(ex => (sess.exercises?.[ex.id]?.sets || []).filter(s => !s.warmup).length > 0).length >= Math.ceil(exList.length / 2);
    return { date, dow: actualDow, day: DEFAULT_PROGRAM[actualDow], isTraining, done, hasSess: !!sess };
  });

  // Bodyweight chart
  const bwPoints = [...bodyweights].sort((a, b) => a.date.localeCompare(b.date)).slice(-14).map(b => ({
    y: b.weight, label: fmt(b.date),
  }));

  function logBodyweight() {
    const w = parseFloat(bwStr);
    if (!w) return;
    onSaveBodyweight(w);
    setBwStr("");
    setBwSaved(true);
    setTimeout(() => setBwSaved(false), 2000);
  }

  return (
    <div className="fade-in" style={{ padding: 20, paddingBottom: 100 }}>
      {/* Streak */}
      <div style={{ ...s.card, ...s.cardGlow, padding: 20, marginBottom: 16, display: "flex", alignItems: "center", gap: 16 }}>
        <div style={{ fontSize: 48, lineHeight: 1 }}>🔥</div>
        <div>
          <div style={{ fontSize: 36, fontWeight: 800, color: "var(--amber)", lineHeight: 1 }}>{weeks}</div>
          <div style={{ fontSize: 13, color: "var(--text-2)", marginTop: 2 }}>consecutive week{weeks !== 1 ? "s" : ""}</div>
          {weeks === 0 && <div style={{ fontSize: 11, color: "var(--text-3)", marginTop: 2 }}>Log a session to start your streak</div>}
        </div>
      </div>

      {/* This week */}
      <div style={{ ...s.card, padding: 16, marginBottom: 16 }}>
        <div style={{ ...s.label, marginBottom: 10 }}>THIS WEEK</div>
        <div style={{ display: "flex", gap: 4 }}>
          {weekSessions.map((ws, i) => (
            <div key={i} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
              <div style={{ fontSize: 10, fontWeight: 700, color: ws.dow === todayDow() ? "var(--accent)" : ws.isTraining ? "var(--text-3)" : "var(--text-3)", opacity: ws.isTraining ? 1 : 0.45 }}>
                {ws.day.short}
              </div>
              {ws.isTraining ? (
                <div style={{
                  width: 32, height: 32, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14,
                  background: ws.done ? "rgba(52,211,153,0.15)" : "var(--bg-2)",
                  border: ws.dow === todayDow() ? "1px solid rgba(79,143,255,0.4)" : ws.done ? "1px solid rgba(52,211,153,0.2)" : "1px solid rgba(255,255,255,0.04)",
                }}>
                  {ws.done ? "✓" : <span style={{ width: 6, height: 6, borderRadius: 3, background: "rgba(255,255,255,0.15)", display: "block" }} />}
                </div>
              ) : (
                <div style={{ width: 32, height: 32, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <div style={{ width: 16, height: 1, background: "rgba(255,255,255,0.08)", borderRadius: 1 }} />
                </div>
              )}
              <div style={{ fontSize: 9, fontWeight: 600, textAlign: "center", lineHeight: 1.2,
                color: ws.isTraining ? (ws.done ? "var(--green)" : "var(--text-3)") : "var(--text-3)",
                opacity: ws.isTraining ? 1 : 0.35,
              }}>
                {ws.isTraining ? ws.day.name : "rest"}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Strength progress */}
      <div style={{ ...s.card, padding: 16, marginBottom: 16 }}>
        <div style={{ ...s.label, marginBottom: 14 }}>STRENGTH PROGRESS</div>
        {[
          { id: "bench-press", name: "Bench Press", color: "#3b82f6" },
          { id: "deadlift", name: "Deadlift", color: "#10b981" },
          { id: "back-squat", name: "Back Squat", color: "#8b5cf6" },
          { id: "ohp", name: "OHP", color: "#f59e0b" },
          { id: "barbell-row", name: "Barbell Row", color: "#3b82f6" },
        ].map(lift => {
          const hist = getExerciseHistory(sessions, lift.id, 8);
          const points = hist.slice().reverse().map(h => {
            const ws = h.sets.filter(s => !s.warmup);
            if (!ws.length) return null;
            return { y: ws[ws.length - 1].weight, label: fmt(h.date) };
          }).filter(Boolean);
          if (points.length < 2) return null;
          return (
            <div key={lift.id} style={{ marginBottom: 16, paddingBottom: 16, borderBottom: "1px solid rgba(255,255,255,0.04)" }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: lift.color, marginBottom: 6 }}>{lift.name}</div>
              <LineChart points={points} color={lift.color} height={70} unit=" lbs" />
            </div>
          );
        }).filter(Boolean)}
        {(() => {
          const anyData = ["bench-press","deadlift","back-squat","ohp","barbell-row"].some(id => getExerciseHistory(sessions, id, 2).length >= 2);
          return !anyData ? <div style={{ fontSize: 12, color: "var(--text-3)", textAlign: "center", padding: "8px 0" }}>Log at least 2 sessions to see trends</div> : null;
        })()}
      </div>

      {/* Bodyweight */}
      <div style={{ ...s.card, padding: 16, marginBottom: 16 }}>
        <div style={{ ...s.label, marginBottom: 10 }}>BODYWEIGHT</div>
        <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
          <input type="number" inputMode="decimal" value={bwStr} onChange={e => setBwStr(e.target.value)}
            placeholder={todayBw ? String(todayBw.weight) : "Today's weight"}
            style={{ ...s.inp, flex: 1, fontSize: 16, padding: "10px 14px" }} />
          <button onClick={logBodyweight} style={{ ...s.btnP, padding: "10px 16px", fontSize: 14, fontFamily: "inherit", flexShrink: 0 }}>
            {bwSaved ? "✓" : "Log"}
          </button>
        </div>
        {bwPoints.length >= 2 ? (
          <LineChart points={bwPoints} color="#a78bfa" unit=" lbs" height={90} />
        ) : (
          <div style={{ fontSize: 12, color: "var(--text-3)", textAlign: "center", padding: "10px 0" }}>
            Log bodyweight daily to see trend
          </div>
        )}
        {todayBw && <div style={{ fontSize: 12, color: "var(--text-3)", textAlign: "center", marginTop: 6 }}>Today: <span style={{ fontWeight: 800, color: "var(--text-1)" }}>{todayBw.weight} lbs</span></div>}
      </div>

      {/* Recent sessions summary */}
      <div style={{ ...s.card, padding: 16 }}>
        <div style={{ ...s.label, marginBottom: 10 }}>RECENT SESSIONS</div>
        {Object.entries(sessions).sort((a, b) => b[0].localeCompare(a[0])).slice(0, 6).map(([date, sess]) => {
          const day = DEFAULT_PROGRAM[sess.dayIndex];
          if (!day || !day.name) return null;
          const exList = getDayExercises(sess.dayIndex, data.customProgram);
          const completed = exList.filter(ex => (sess.exercises?.[ex.id]?.sets || []).filter(s => !s.warmup).length > 0).length;
          const prs = Object.values(sess.exercises || {}).flatMap(ex => (ex.sets || []).filter(s => s.pr)).length;
          const totalVolume = Object.values(sess.exercises || {}).reduce((sum, ex) => {
            return sum + (ex.sets || []).filter(s => !s.warmup).reduce((s2, st) => s2 + st.weight * st.reps, 0);
          }, 0);
          const isExpanded = expandedSession === date;

          return (
            <div key={date} style={{ borderBottom: "1px solid rgba(255,255,255,0.03)" }}>
              {/* Summary row — tap to expand */}
              <button onClick={() => setExpandedSession(isExpanded ? null : date)} style={{
                width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "10px 0", background: "none", border: "none", cursor: "pointer", fontFamily: "inherit", textAlign: "left",
              }}>
                <div style={{ flex: 1, marginRight: 8 }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: day.color || "var(--text-1)" }}>{day.name}</div>
                  <div style={{ fontSize: 11, color: "var(--text-3)" }}>{fmt(date)} · {completed}/{exList.length} exercises</div>
                  {sess.notes?.trim() && <div style={{ fontSize: 11, color: "var(--text-2)", marginTop: 2, fontStyle: "italic" }}>"{sess.notes.trim()}"</div>}
                </div>
                <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 2 }}>
                  {prs > 0 && <div style={{ fontSize: 11, fontWeight: 800, color: "var(--amber)" }}>🏆 {prs} PR{prs > 1 ? "s" : ""}</div>}
                  {totalVolume > 0 && <div style={{ fontSize: 11, fontWeight: 700, color: "var(--text-3)" }}>{totalVolume.toLocaleString()} lbs</div>}
                  {(Array.isArray(sess.cardio) ? sess.cardio : sess.cardio ? [sess.cardio] : []).map((c, i) => (
                    <div key={i} style={{ fontSize: 10, color: "var(--green)" }}>{c.type} {c.duration}m</div>
                  ))}
                  <span style={{ fontSize: 12, color: "var(--text-3)", marginTop: 2 }}>{isExpanded ? "▲" : "▼"}</span>
                </div>
              </button>

              {/* Expanded detail */}
              {isExpanded && (
                <div style={{ paddingBottom: 12 }}>
                  {exList.map(ex => {
                    const exData = sess.exercises?.[ex.id];
                    const ws = (exData?.sets || []).filter(s => !s.warmup);
                    if (!ws.length) return null;
                    const exVolume = ws.reduce((sum, st) => sum + st.weight * st.reps, 0);
                    const exPR = ws.some(s => s.pr);
                    const topSet = ws.reduce((best, st) => !best || st.weight > best.weight ? st : best, null);
                    return (
                      <div key={ex.id} style={{
                        display: "flex", alignItems: "center", justifyContent: "space-between",
                        padding: "7px 10px", borderRadius: 8, marginBottom: 3,
                        background: exPR ? "rgba(251,191,36,0.05)" : "rgba(255,255,255,0.02)",
                      }}>
                        <div>
                          <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
                            <span style={{ fontSize: 13, fontWeight: 700, color: "var(--text-1)" }}>{ex.name}</span>
                            {exPR && <span style={{ fontSize: 9, fontWeight: 800, padding: "1px 5px", borderRadius: 4, background: "var(--amber-dim)", color: "var(--amber)" }}>PR</span>}
                          </div>
                          <div style={{ fontSize: 11, color: "var(--text-3)", marginTop: 1 }}>
                            {ws.length} set{ws.length > 1 ? "s" : ""} · {ws.map(st => `${st.weight}×${st.reps}`).join("  ")}
                          </div>
                        </div>
                        <div style={{ textAlign: "right" }}>
                          <div style={{ fontSize: 12, fontWeight: 700, color: day.color, opacity: 0.8 }}>
                            {topSet.weight} lbs
                          </div>
                          <div style={{ fontSize: 10, color: "var(--text-3)" }}>{exVolume.toLocaleString()} vol</div>
                        </div>
                      </div>
                    );
                  })}
                  {(Array.isArray(sess.cardio) ? sess.cardio : sess.cardio ? [sess.cardio] : []).length > 0 && (
                    <div style={{ padding: "6px 10px", borderRadius: 8, background: "rgba(52,211,153,0.05)", marginTop: 4 }}>
                      <div style={{ fontSize: 11, fontWeight: 700, color: "var(--green)", marginBottom: 2 }}>Cardio</div>
                      {(Array.isArray(sess.cardio) ? sess.cardio : [sess.cardio]).map((c, i) => (
                        <div key={i} style={{ fontSize: 12, color: "var(--text-2)" }}>
                          {c.type} · {c.duration}min{c.incline ? ` · ${c.incline}% incline` : ""}{c.speed ? ` · ${c.speed} mph` : ""}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

