function PlateCalc() {
  const [targetStr, setTargetStr] = useState("135");
  const [bar, setBar] = useState(45);
  const target = Number(targetStr) || 0;
  const plates = calcPlates(target, bar);
  const actual = bar + plates.reduce((a, p) => a + p, 0) * 2;
  const colors = { 45: "#ef4444", 35: "#f59e0b", 25: "#22c55e", 10: "#3b82f6", 5: "#8b5cf6", 2.5: "#ec4899" };
  function adjust(v) { const n = Math.max(bar, target + v); setTargetStr(String(n)); }
  return (
    <div>
      <div style={{ marginBottom: 14 }}>
        <div style={s.label}>BAR</div>
        <div style={{ display: "flex", gap: 5 }}>
          {[45, 35, 25, 15].map(b => (
            <button key={b} onClick={() => setBar(b)} style={{
              flex: 1, padding: "10px 0", borderRadius: 10, fontSize: 14, fontWeight: 700, border: "none", cursor: "pointer", fontFamily: "inherit",
              background: bar === b ? "rgba(79,143,255,0.12)" : "var(--bg-2)", color: bar === b ? "#4f8fff" : "var(--text-3)",
            }}>{b}</button>
          ))}
        </div>
      </div>
      <div style={{ marginBottom: 16 }}>
        <div style={s.label}>TARGET WEIGHT</div>
        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
          <button onClick={() => adjust(-10)} style={{ ...s.btnG, minWidth: 40, height: 48, fontSize: 12, fontWeight: 800, color: "var(--red)", padding: "0 6px", borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center" }}>-10</button>
          <button onClick={() => adjust(-5)} style={{ ...s.btnG, minWidth: 36, height: 48, fontSize: 12, fontWeight: 800, color: "var(--red)", padding: "0 6px", borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center" }}>-5</button>
          <input type="number" inputMode="numeric" value={targetStr} onChange={e => setTargetStr(e.target.value)} onBlur={() => { if (!targetStr) setTargetStr("0"); }}
            style={{ flex: 1, minWidth: 0, textAlign: "center", fontSize: 28, fontWeight: 800, padding: "8px 4px", borderRadius: 12, background: "var(--bg-2)", color: "var(--text-1)", border: "1px solid rgba(255,255,255,0.06)", outline: "none", fontFamily: "inherit" }} />
          <button onClick={() => adjust(5)} style={{ ...s.btnG, minWidth: 36, height: 48, fontSize: 12, fontWeight: 800, color: "var(--green)", padding: "0 6px", borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center" }}>+5</button>
          <button onClick={() => adjust(10)} style={{ ...s.btnG, minWidth: 40, height: 48, fontSize: 12, fontWeight: 800, color: "var(--green)", padding: "0 6px", borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center" }}>+10</button>
        </div>
      </div>
      {target > bar ? (
        <div style={{ ...s.card, ...s.cardGlow, padding: 18 }}>
          <div style={{ ...s.label, marginBottom: 10 }}>EACH SIDE — {(target - bar) / 2} LBS</div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
            {plates.map((p, i) => (
              <div key={i} style={{ padding: "10px 18px", borderRadius: 10, fontSize: 17, fontWeight: 800, background: `${colors[p]}15`, color: colors[p], border: `1px solid ${colors[p]}30` }}>{p}</div>
            ))}
          </div>
          {actual !== target && <div style={{ fontSize: 12, color: "var(--amber)" }}>Closest loadable: {actual} lbs</div>}
        </div>
      ) : (
        <div style={{ ...s.card, padding: 18, textAlign: "center", color: "var(--text-3)" }}>Just the bar!</div>
      )}
    </div>
  );
}

function OneRMCalc() {
  const [weightStr, setWeightStr] = useState("185");
  const [repsStr, setRepsStr] = useState("5");
  const weight = Number(weightStr) || 0;
  const reps = Math.max(1, Number(repsStr) || 1);
  const orm = calc1RM(weight, reps);
  const pcts = [100, 95, 90, 85, 80, 75, 70, 65, 60];
  return (
    <div style={{ contain: "layout style" }}>
      <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
        <div style={{ flex: 1 }}>
          <div style={s.label}>WEIGHT (LBS)</div>
          <input type="number" inputMode="numeric" value={weightStr} onChange={e => setWeightStr(e.target.value)} onBlur={() => { if (!weightStr) setWeightStr("0"); }}
            style={{ ...s.inp, textAlign: "center", fontSize: 22, fontWeight: 800, padding: "10px 0", height: 52 }} />
        </div>
        <div style={{ flex: 1 }}>
          <div style={s.label}>REPS</div>
          <input type="number" inputMode="numeric" value={repsStr} onChange={e => setRepsStr(e.target.value)} onBlur={() => { if (!repsStr) setRepsStr("1"); }}
            style={{ ...s.inp, textAlign: "center", fontSize: 22, fontWeight: 800, padding: "10px 0", height: 52 }} />
        </div>
      </div>
      <div style={{ ...s.card, ...s.cardGlow, padding: 18, textAlign: "center", marginBottom: 16 }}>
        <div style={{ ...s.label, marginBottom: 2 }}>ESTIMATED 1RM</div>
        <div style={{ fontSize: 36, fontWeight: 800, color: "var(--accent)" }}>{orm} <span style={{ fontSize: 14, color: "var(--text-3)" }}>lbs</span></div>
        <div style={{ fontSize: 11, color: "var(--text-3)", marginTop: 2 }}>Epley formula</div>
      </div>
      <div style={{ ...s.label, marginBottom: 6 }}>PERCENTAGE TABLE</div>
      {pcts.map(p => (
        <div key={p} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "9px 12px", borderRadius: 9, marginBottom: 2, background: p === 100 ? "rgba(79,143,255,0.06)" : "var(--bg-2)", height: 40 }}>
          <span style={{ fontSize: 13, fontWeight: 700, color: p === 100 ? "var(--accent)" : "var(--text-2)" }}>{p}%</span>
          <span style={{ fontSize: 15, fontWeight: 800, fontVariantNumeric: "tabular-nums" }}>{Math.round(orm * p / 100)} lbs</span>
        </div>
      ))}
    </div>
  );
}

/* ═══════════════════════════════════════════════
   SETTINGS VIEW
   ═══════════════════════════════════════════════ */
function SettingsView({ data, settings, onSave, onReset, onOpenProgramEditor, onImport }) {
  const [crStr, setCrStr] = useState(String(settings.compoundRest || 180));
  const [irStr, setIrStr] = useState(String(settings.isolationRest || 90));
  const [confirm, setConfirm] = useState(false);
  const [saved, setSaved] = useState(false);

  return (
    <div className="fade-in" style={{ padding: 20, paddingBottom: 100 }}>
      <h2 style={{ fontSize: 20, fontWeight: 800, marginBottom: 16 }}>Settings</h2>

      {/* Program editor */}
      <button onClick={onOpenProgramEditor} style={{
        width: "100%", padding: "16px 20px", borderRadius: 14, fontSize: 15, fontWeight: 700, border: "none", cursor: "pointer", fontFamily: "inherit",
        background: "var(--bg-2)", color: "var(--text-1)", display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20,
        border: "1px solid rgba(255,255,255,0.06)",
      }}>
        <span>Edit Program</span>
        <span style={{ color: "var(--text-3)", fontSize: 18 }}>›</span>
      </button>

      <div style={{ marginBottom: 16 }}>
        <div style={s.label}>COMPOUND REST (SEC)</div>
        <input type="number" inputMode="numeric" value={crStr} onChange={e => setCrStr(e.target.value)} onBlur={() => { if (!crStr) setCrStr("180"); }} style={{ ...s.inp, fontSize: 18 }} />
      </div>
      <div style={{ marginBottom: 20 }}>
        <div style={s.label}>ISOLATION REST (SEC)</div>
        <input type="number" inputMode="numeric" value={irStr} onChange={e => setIrStr(e.target.value)} onBlur={() => { if (!irStr) setIrStr("90"); }} style={{ ...s.inp, fontSize: 18 }} />
      </div>
      <button onClick={() => {
        onSave({ compoundRest: Number(crStr) || 180, isolationRest: Number(irStr) || 90 });
        setSaved(true);
        setTimeout(() => setSaved(false), 2000);
      }} style={{ ...s.btnP, width: "100%", height: 50, fontSize: 15, fontFamily: "inherit", marginBottom: 12 }}>
        {saved ? "✓ Saved" : "Save Settings"}
      </button>

      {/* Export */}
      <button onClick={() => exportData(data)} style={{
        width: "100%", height: 50, borderRadius: 14, fontSize: 15, fontWeight: 700, border: "none", cursor: "pointer", fontFamily: "inherit",
        background: "rgba(52,211,153,0.08)", color: "var(--green)", border: "1px solid rgba(52,211,153,0.15)", marginBottom: 8,
      }}>
        Export Backup (JSON)
      </button>

      {/* Import */}
      <label style={{
        display: "block", width: "100%", height: 50, borderRadius: 14, fontSize: 15, fontWeight: 700,
        background: "rgba(79,143,255,0.08)", color: "var(--accent)", border: "1px solid rgba(79,143,255,0.15)",
        cursor: "pointer", textAlign: "center", lineHeight: "50px", marginBottom: 28,
      }}>
        Import Backup (JSON)
        <input type="file" accept=".json" style={{ display: "none" }} onChange={e => {
          const file = e.target.files?.[0];
          if (!file) return;
          const reader = new FileReader();
          reader.onload = evt => {
            try {
              const parsed = JSON.parse(evt.target.result);
              if (parsed.sessions) {
                onImport(parsed);
                alert("Backup restored successfully.");
              } else {
                alert("Invalid backup file.");
              }
            } catch { alert("Could not read file."); }
          };
          reader.readAsText(file);
          e.target.value = "";
        }} />
      </label>

      <div style={{ borderTop: "1px solid rgba(255,255,255,0.05)", paddingTop: 20 }}>
        {!confirm ? (
          <button onClick={() => setConfirm(true)} style={{ width: "100%", padding: "14px 0", borderRadius: 14, fontSize: 14, fontWeight: 700, border: "none", cursor: "pointer", fontFamily: "inherit", background: "var(--red-dim)", color: "var(--red)" }}>
            Reset All Data
          </button>
        ) : (
          <div>
            <p style={{ fontSize: 14, color: "var(--red)", textAlign: "center", marginBottom: 10 }}>Delete all history?</p>
            <div style={{ display: "flex", gap: 8 }}>
              <button onClick={() => setConfirm(false)} style={{ ...s.btnG, flex: 1, padding: "14px 0", fontSize: 14, fontFamily: "inherit" }}>Cancel</button>
              <button onClick={() => { onReset(); setConfirm(false); }} style={{ ...s.btnP, flex: 1, padding: "14px 0", fontSize: 14, fontFamily: "inherit", background: "linear-gradient(135deg, #ef4444, #dc2626)" }}>Confirm</button>
            </div>
          </div>
        )}
      </div>

      <div style={{ textAlign: "center", paddingTop: 16 }}>
        <span style={{ fontSize: 11, color: "var(--text-3)", fontWeight: 600 }}>Gymingify v{APP_VERSION}</span>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════
   MAIN APP
   ═══════════════════════════════════════════════ */
export default function App() {
  const [data, setData] = useState(null);
  const [tab, setTab] = useState("workout");
  const [loggingEx, setLoggingEx] = useState(null);
  const [activeDow, setActiveDow] = useState(todayDow());
  const [showProgramEditor, setShowProgramEditor] = useState(false);

  const [timerEndTime, setTimerEndTime] = useState(null);
  const [timerTotalSecs, setTimerTotalSecs] = useState(0);

  useEffect(() => { loadData().then(setData); }, []);
  const persist = useCallback(nd => { setData(nd); saveData(nd); }, []);

  function handleStartTimer(secs) { requestNotifPermission(); setTimerEndTime(Date.now() + secs * 1000); setTimerTotalSecs(secs); }
  function handleDismissTimer() { setTimerEndTime(null); }

  if (!data) return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "100dvh", background: "#06090f" }}>
      <style>{CSS}</style>
      <span style={{ color: "#4a5978", fontSize: 14 }}>Loading...</span>
    </div>
  );

  const today = todayStr();

  function ensureSession() {
    if (!data.sessions[today]) return { ...data, sessions: { ...data.sessions, [today]: { dayIndex: todayDow(), exercises: {}, notes: "", startTime: Date.now() } } };
    return data;
  }
  function handleSaveSets(exId, sets, swappedTo, exName) {
    let d = ensureSession();
    const se = { ...d.sessions[today] };
    se.exercises = { ...se.exercises, [exId]: { ...se.exercises[exId], sets, swappedTo, skipped: false, name: exName } };
    persist({ ...d, sessions: { ...d.sessions, [today]: se } });
  }
  function handleSkip(exId, currentlySkipped) {
    let d = ensureSession();
    const se = { ...d.sessions[today] };
    if (currentlySkipped) {
      se.exercises = { ...se.exercises, [exId]: { ...se.exercises[exId], skipped: false } };
    } else {
      se.exercises = { ...se.exercises, [exId]: { ...se.exercises[exId], skipped: true } };
    }
    persist({ ...d, sessions: { ...d.sessions, [today]: se } });
  }
  function handleSaveNotes(notes) {
    let d = ensureSession();
    persist({ ...d, sessions: { ...d.sessions, [today]: { ...d.sessions[today], notes } } });
  }
  function handleSaveCardio(cardioEntry) {
    let d = ensureSession();
    const existing = Array.isArray(d.sessions[today]?.cardio)
      ? d.sessions[today].cardio
      : d.sessions[today]?.cardio ? [d.sessions[today].cardio] : [];
    persist({ ...d, sessions: { ...d.sessions, [today]: { ...d.sessions[today], cardio: [...existing, cardioEntry] } } });
  }
  function handleRemoveCardio(index) {
    let d = ensureSession();
    const existing = Array.isArray(d.sessions[today]?.cardio) ? d.sessions[today].cardio : [];
    persist({ ...d, sessions: { ...d.sessions, [today]: { ...d.sessions[today], cardio: existing.filter((_, i) => i !== index) } } });
  }
  function handleSaveBodyweight(weight) {
    const existing = (data.bodyweights || []).filter(b => b.date !== today);
    persist({ ...data, bodyweights: [...existing, { date: today, weight }] });
  }
  function handleSaveProgram(customProgram) {
    persist({ ...data, customProgram });
  }

  const rd = { compound: data.settings?.compoundRest || 180, isolation: data.settings?.isolationRest || 90 };
  const timerActive = timerEndTime && timerEndTime > Date.now() - 3000;

  const navItems = [
    { id: "workout", icon: "🏋️", label: "Workout" },
    { id: "history", icon: "📋", label: "History" },
    { id: "stats", icon: "📈", label: "Stats" },
    { id: "tools", icon: "🔧", label: "Tools" },
    { id: "settings", icon: "⚙️", label: "Settings" },
  ];

  return (
    <div style={{ height: "100dvh", maxWidth: "100vw", display: "flex", flexDirection: "column", background: "var(--bg-0)", overflow: "hidden" }}>
      <style>{CSS}</style>
      <div style={{ flexShrink: 0, height: "env(safe-area-inset-top)", background: "var(--bg-0)" }} />

      {tab === "workout" && !loggingEx && (
        <div style={{ flexShrink: 0, padding: "10px 16px 4px", display: "flex", justifyContent: "center", gap: 3 }}>
          {DEFAULT_PROGRAM.map((d, i) => {
            const isT = i === todayDow();
            const active = i === activeDow;
            const training = getDayExercises(i, data.customProgram).length > 0;
            return (
              <button key={i} onClick={() => setActiveDow(i)} style={{
                width: 44, height: 48, borderRadius: 10, border: "none", cursor: "pointer", fontFamily: "inherit",
                display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 3,
                background: active ? (d.color ? `${d.color}15` : "rgba(79,143,255,0.1)") : "transparent",
                transition: "all 0.15s",
              }}>
                <span style={{ fontSize: 11, fontWeight: active ? 800 : 600, color: active ? (d.color || "var(--accent)") : "var(--text-3)" }}>{d.short}</span>
                {training ? (
            <div style={{ width: 5, height: 5, borderRadius: 3, background: isT ? (active ? (d.color || "#fff") : "var(--accent)") : "rgba(255,255,255,0.08)" }} />
          ) : (
            <div style={{ width: 14, height: 1, borderRadius: 1, background: active ? "rgba(255,255,255,0.2)" : "rgba(255,255,255,0.1)" }} />
          )}
              </button>
            );
          })}
        </div>
      )}

      <div style={{ flex: 1, overflow: "auto", overflowX: "hidden", overflowAnchor: "none", WebkitOverflowScrolling: "touch" }}>
        {tab === "workout" && <WorkoutView data={data} activeDow={activeDow} onStartExercise={setLoggingEx} onSkip={handleSkip} onSaveNotes={handleSaveNotes} onSaveCardio={handleSaveCardio} onRemoveCardio={handleRemoveCardio} />}
        {tab === "history" && <HistoryView data={data} />}
        {tab === "stats" && <StatsView data={data} onSaveBodyweight={handleSaveBodyweight} />}
        {tab === "tools" && <ToolsView />}
        {tab === "settings" && <SettingsView data={data} settings={data.settings || {}} onSave={st => persist({ ...data, settings: st })} onReset={() => persist({ ...defaultData })} onOpenProgramEditor={() => setShowProgramEditor(true)} onImport={imported => persist({ ...defaultData, ...imported })} />}
      </div>

      {timerActive && !loggingEx && <RestTimer endTime={timerEndTime} totalSeconds={timerTotalSecs} onDismiss={handleDismissTimer} />}

      {!loggingEx && (
        <div style={{
          flexShrink: 0, display: "flex", background: "var(--bg-1)", borderTop: "1px solid rgba(255,255,255,0.04)",
          paddingBottom: "max(6px, env(safe-area-inset-bottom))",
        }}>
          {navItems.map(n => (
            <button key={n.id} onClick={() => { setTab(n.id); if (n.id === "workout") setActiveDow(todayDow()); }}
              style={{
                flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 2,
                padding: "8px 0 4px", border: "none", cursor: "pointer", background: "transparent", fontFamily: "inherit",
                color: tab === n.id ? "var(--accent)" : "var(--text-3)", transition: "color 0.15s",
              }}>
              <span style={{ fontSize: 16 }}>{n.icon}</span>
              <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: 0.3 }}>{n.label}</span>
            </button>
          ))}
        </div>
      )}

      {loggingEx && (
        <LoggingScreen exercise={loggingEx} sessions={data.sessions} dayIndex={activeDow}
          onSave={handleSaveSets} onClose={() => setLoggingEx(null)} restDefaults={rd}
          timerEndTime={timerEndTime} timerTotalSecs={timerTotalSecs}
          onStartTimer={handleStartTimer} onDismissTimer={handleDismissTimer} />
      )}

      {showProgramEditor && (
        <ProgramEditorScreen data={data} onSave={handleSaveProgram} onClose={() => setShowProgramEditor(false)} />
      )}
    </div>
  );
}